package com.luizin.lembreteagua;
import android.app.*; import android.content.*; import android.os.Build;
public class AlarmReceiver extends BroadcastReceiver { public static final String CHANNEL_ID="agua_lembrete"; public static final int NOTIFICATION_ID=777;
 public void onReceive(Context c,Intent in){createChannel(c);int rc=in!=null?in.getIntExtra("requestCode",0):0;Intent ai=new Intent(c,AlarmActivity.class);ai.putExtra("requestCode",rc);ai.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent fs=PendingIntent.getActivity(c,9000+rc,ai,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,CHANNEL_ID):new Notification.Builder(c);b.setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle("Hora de beber água!").setContentText("Letícia, vai pegar um copo de água agora!!!").setCategory(Notification.CATEGORY_ALARM).setPriority(Notification.PRIORITY_MAX).setAutoCancel(true).setContentIntent(fs).setFullScreenIntent(fs,true);NotificationManager manager=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(manager!=null)manager.notify(NOTIFICATION_ID,b.build()); ReminderScheduler.scheduleAll(c);}
 private void createChannel(Context c){if(Build.VERSION.SDK_INT>=26){NotificationManager manager=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(manager==null)return;NotificationChannel ch=new NotificationChannel(CHANNEL_ID,"Lembretes de água",NotificationManager.IMPORTANCE_HIGH);ch.enableVibration(true);ch.setLockscreenVisibility(Notification.VISIBILITY_PUBLIC);manager.createNotificationChannel(ch);}}
}
